#!/usr/bin/env python3
"""Validate repository-level Agent Skill naming and UI metadata."""

from __future__ import annotations

import re
import sys
from pathlib import Path


NAME_RE = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def parse_frontmatter(skill_md: Path) -> dict[str, str]:
    text = skill_md.read_text(encoding="utf-8")
    if not text.startswith("---\n"):
        raise ValueError("missing opening YAML frontmatter delimiter")
    try:
        frontmatter, _ = text[4:].split("\n---\n", 1)
    except ValueError as exc:
        raise ValueError("missing closing YAML frontmatter delimiter") from exc

    values: dict[str, str] = {}
    for line in frontmatter.splitlines():
        if not line.strip():
            continue
        if ":" not in line:
            raise ValueError(f"unsupported frontmatter line: {line!r}")
        key, value = line.split(":", 1)
        values[key.strip()] = value.strip()
    return values


def validate_skill(skill_dir: Path) -> list[str]:
    errors: list[str] = []
    skill_md = skill_dir / "SKILL.md"
    openai_yaml = skill_dir / "agents" / "openai.yaml"

    if not skill_md.is_file():
        return [f"{skill_dir}: missing SKILL.md"]

    try:
        frontmatter = parse_frontmatter(skill_md)
    except ValueError as exc:
        return [f"{skill_md}: {exc}"]

    if set(frontmatter) != {"name", "description"}:
        errors.append(
            f"{skill_md}: frontmatter must contain only name and description"
        )

    name = frontmatter.get("name", "")
    if not NAME_RE.fullmatch(name):
        errors.append(f"{skill_md}: invalid Skill name {name!r}")
    if name != skill_dir.name:
        errors.append(
            f"{skill_md}: name {name!r} must match directory {skill_dir.name!r}"
        )
    if not frontmatter.get("description"):
        errors.append(f"{skill_md}: description must not be empty")

    if not openai_yaml.is_file():
        errors.append(f"{openai_yaml}: missing UI metadata")
    elif f"${name}" not in openai_yaml.read_text(encoding="utf-8"):
        errors.append(f"{openai_yaml}: default prompt must invoke ${name}")

    return errors


def main() -> int:
    repo_root = Path(__file__).resolve().parent.parent
    skills_root = repo_root / "skills"
    skill_dirs = sorted(path for path in skills_root.iterdir() if path.is_dir())
    errors: list[str] = []

    for unwanted in skills_root.rglob("*"):
        if unwanted.name == ".DS_Store" or "__pycache__" in unwanted.parts:
            errors.append(f"{unwanted}: generated file must not be committed")

    for skill_dir in skill_dirs:
        errors.extend(validate_skill(skill_dir))

    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    print(f"Validated {len(skill_dirs)} Skill directories.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Validate repository docs, example data, and generated style assets."""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parent.parent
SKILL_ID = "linggan-talking-cards"
STYLES = [
    "apple-flat",
    "candy",
    "obsidian",
    "neo-brutalism",
    "swiss",
    "blueprint",
    "bento",
    "notebook",
    "bauhaus",
    "zen-ink",
]


def speech_normalize(value: str) -> str:
    value = value.replace("**", "").replace("__", "")
    value = re.sub(r"(?m)^\s*[•*-]\s*", "", value)
    return re.sub(r"\s+", "", value)


def main() -> int:
    errors: list[str] = []
    readmes = [ROOT / "README.md", ROOT / "README.zh-CN.md"]
    skill_dir = ROOT / "skills" / SKILL_ID
    manifest_path = ROOT / "examples" / "style-gallery-manifest.json"

    required_files = [
        ROOT / "LICENSE",
        skill_dir / "SKILL.md",
        skill_dir / "agents" / "openai.yaml",
        skill_dir / "package.json",
        skill_dir / "scripts" / "render_cards.py",
        skill_dir / "scripts" / "render_page.js",
        skill_dir / "references" / "manifest-schema.md",
        skill_dir / "references" / "styles.md",
        manifest_path,
        *readmes,
    ]
    for path in required_files:
        if not path.is_file():
            errors.append(f"missing required file: {path.relative_to(ROOT)}")

    if manifest_path.is_file():
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        transcripts = "".join(card.get("transcript", "") for card in manifest.get("cards", []))
        if speech_normalize(transcripts) != speech_normalize(manifest.get("source_text", "")):
            errors.append("example transcripts do not exactly cover source_text")
        if not 3 <= len(manifest.get("cards", [])) <= 10:
            errors.append("example manifest must contain 3 to 10 cards")

    expected_assets = [
        ROOT / "assets" / "readme" / "styles" / f"{index:02d}-{style_id}.webp"
        for index, style_id in enumerate(STYLES, start=1)
    ]
    for asset in expected_assets:
        if not asset.is_file() or asset.stat().st_size == 0:
            errors.append(f"missing style preview: {asset.relative_to(ROOT)}")

    for readme in readmes:
        if not readme.is_file():
            continue
        text = readme.read_text(encoding="utf-8")
        if f"${SKILL_ID}" not in text:
            errors.append(f"{readme.name} does not show the ${SKILL_ID} invocation")
        for asset in expected_assets:
            relative = f"./{asset.relative_to(ROOT).as_posix()}"
            if relative not in text:
                errors.append(f"{readme.name} does not reference {relative}")

    stale_names = [
        "yh-" + "talking-cards-skill",
        "$talking-" + "script-ppt-cards",
    ]
    text_files = [
        *ROOT.glob("README*.md"),
        *skill_dir.rglob("*.md"),
        *skill_dir.rglob("*.yaml"),
        *skill_dir.rglob("*.json"),
    ]
    for path in text_files:
        text = path.read_text(encoding="utf-8")
        for stale in stale_names:
            if stale in text:
                errors.append(f"{path.relative_to(ROOT)} contains stale name {stale!r}")

    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    print(f"Validated {len(STYLES)} README style previews and the public example manifest.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env node

const fs = require("fs");
const os = require("os");
const path = require("path");
const { pathToFileURL } = require("url");

function loadPlaywright() {
  const candidates = [];
  if (process.env.CARD_RENDER_PLAYWRIGHT) {
    candidates.push(process.env.CARD_RENDER_PLAYWRIGHT);
  }
  candidates.push("playwright");
  candidates.push(
    path.join(
      os.homedir(),
      ".cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright",
    ),
  );

  const failures = [];
  for (const candidate of candidates) {
    try {
      return require(candidate);
    } catch (error) {
      failures.push(`${candidate}: ${error.code || error.message}`);
    }
  }
  throw new Error(
    "Playwright is unavailable. Run `npm install` and `npm run setup` in the Skill directory, " +
      "or set CARD_RENDER_PLAYWRIGHT to its package directory. " +
      failures.join(" | "),
  );
}

async function renderCard(args) {
  const [htmlPath, outputPath, widthText, heightText] = args;
  const width = Number(widthText);
  const height = Number(heightText);
  if (!htmlPath || !outputPath || !Number.isInteger(width) || !Number.isInteger(height)) {
    throw new Error("Usage: render_page.js <html> <png> <width> <height>");
  }
  if (!fs.existsSync(htmlPath)) {
    throw new Error(`Render source not found: ${htmlPath}`);
  }

  const { chromium } = loadPlaywright();
  const browser = await chromium.launch({ headless: true });
  try {
    const page = await browser.newPage({
      viewport: { width, height },
      deviceScaleFactor: 1,
    });
    await page.goto(pathToFileURL(path.resolve(htmlPath)).href, {
      waitUntil: "load",
      timeout: 30000,
    });
    await page.evaluate(async () => {
      if (document.fonts && document.fonts.ready) {
        await document.fonts.ready;
      }
    });
    const layoutCheck = await page.evaluate(() => {
      const paper = document.querySelector(".paper");
      const upper = document.querySelector(".upper-content");
      const titleBlock = document.querySelector(".title-block");
      const content = document.querySelector(".content");
      const safe = document.querySelector("[data-avatar-safe-zone]");
      if (!paper || !upper || !titleBlock || !content || !safe) {
        return { missingLayoutRegions: true };
      }
      const paperRect = paper.getBoundingClientRect();
      const safeRect = safe.getBoundingClientRect();
      const heading = titleBlock.querySelector("h1");
      if (!heading) {
        return { missingLayoutRegions: true };
      }
      const headingRect = heading.getBoundingClientRect();
      const contentRect = content.getBoundingClientRect();
      const overlapSize = (first, second) => {
        const width = Math.max(
          0,
          Math.min(first.right, second.right) - Math.max(first.left, second.left),
        );
        const height = Math.max(
          0,
          Math.min(first.bottom, second.bottom) - Math.max(first.top, second.top),
        );
        return { width, height };
      };
      const titleNodes = Array.from(
        document.querySelectorAll(
          ".title-block .eyebrow, .title-block h1, .title-block .summary",
        ),
      );
      const contentNodes = Array.from(
        document.querySelectorAll(
          ".content .number, .content .point-text, .content .highlight, .content .media img",
        ),
      );
      const collisionDetails = (nodes) =>
        nodes
        .map((node) => {
          const overlap = overlapSize(node.getBoundingClientRect(), safeRect);
          return {
            element: node.className || node.tagName.toLowerCase(),
            overlapWidth: overlap.width,
            overlapHeight: overlap.height,
          };
        })
        .filter((item) => item.overlapWidth > 2 && item.overlapHeight > 2);
      const titleVisualBottom = Math.max(
        ...titleNodes.map((node) => node.getBoundingClientRect().bottom),
      );
      return {
        missingLayoutRegions: false,
        overflowX: upper.scrollWidth - upper.clientWidth,
        overflowY: upper.scrollHeight - upper.clientHeight,
        titleTopShare:
          paperRect.height > 0 ? (headingRect.top - paperRect.top) / paperRect.height : 1,
        contentTopShare:
          paperRect.height > 0 ? (contentRect.top - paperRect.top) / paperRect.height : 1,
        contentBottomShare:
          paperRect.height > 0 ? (contentRect.bottom - paperRect.top) / paperRect.height : 0,
        titleContentGap: contentRect.top - titleVisualBottom,
        safeWidthShare: paperRect.width > 0 ? safeRect.width / paperRect.width : 0,
        safeHeightShare: paperRect.height > 0 ? safeRect.height / paperRect.height : 0,
        titleCollisions: collisionDetails(titleNodes),
        preferredSafeZoneCollisions: collisionDetails(contentNodes),
      };
    });
    if (
      layoutCheck.missingLayoutRegions ||
      layoutCheck.overflowX > 1 ||
      layoutCheck.overflowY > 1 ||
      layoutCheck.titleTopShare < 0.03 ||
      layoutCheck.titleTopShare > 0.3 ||
      layoutCheck.contentTopShare < 0.3 ||
      layoutCheck.contentTopShare > 0.55 ||
      layoutCheck.contentBottomShare < 0.62 ||
      layoutCheck.contentBottomShare > 0.94 ||
      layoutCheck.titleContentGap < 8 ||
      layoutCheck.safeWidthShare < 0.18 ||
      layoutCheck.safeHeightShare < 0.18 ||
      layoutCheck.titleCollisions.length > 0
    ) {
      throw new Error(
        "Card content violates the upper-title or overall layout: " +
          JSON.stringify(layoutCheck),
      );
    }
    await page.screenshot({
      path: path.resolve(outputPath),
      type: "png",
      animations: "disabled",
      caret: "hide",
    });
  } finally {
    await browser.close();
  }
}

async function validatePreview(args) {
  const [htmlPath, expectedCountText] = args;
  const expectedCount = Number(expectedCountText);
  if (!htmlPath || !Number.isInteger(expectedCount)) {
    throw new Error("Usage: render_page.js validate-preview <index.html> <card-count>");
  }
  const { chromium } = loadPlaywright();
  const browser = await chromium.launch({ headless: true });
  const checks = [];
  try {
    for (const viewport of [
      { name: "desktop", width: 1440, height: 1000 },
      { name: "mobile", width: 390, height: 844 },
    ]) {
      const page = await browser.newPage({ viewport });
      const consoleErrors = [];
      page.on("console", (message) => {
        if (message.type() === "error") consoleErrors.push(message.text());
      });
      await page.goto(pathToFileURL(path.resolve(htmlPath)).href, {
        waitUntil: "load",
        timeout: 30000,
      });
      await page.waitForFunction(
        () => Array.from(document.images).every((image) => image.complete && image.naturalWidth > 0),
        null,
        { timeout: 30000 },
      );
      const result = await page.evaluate(() => ({
        pageOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
        recordCount: document.querySelectorAll(".record").length,
        transcriptCount: document.querySelectorAll(".transcript").length,
        brokenImages: Array.from(document.images)
          .filter((image) => !image.complete || image.naturalWidth === 0)
          .map((image) => image.getAttribute("src")),
      }));
      result.name = viewport.name;
      result.consoleErrors = consoleErrors;
      if (
        result.pageOverflow !== 0 ||
        result.recordCount !== expectedCount ||
        result.transcriptCount !== expectedCount ||
        result.brokenImages.length ||
        result.consoleErrors.length
      ) {
        throw new Error(`Preview failed at ${viewport.name}: ${JSON.stringify(result)}`);
      }
      checks.push(result);
      await page.close();
    }
  } finally {
    await browser.close();
  }
  process.stdout.write(JSON.stringify(checks));
}

async function validateStyleGallery(args) {
  const [htmlPath, expectedStyleCountText, expectedCardsPerStyleText] = args;
  const expectedStyleCount = Number(expectedStyleCountText);
  const expectedCardsPerStyle = Number(expectedCardsPerStyleText);
  if (
    !htmlPath ||
    !Number.isInteger(expectedStyleCount) ||
    expectedStyleCount < 1 ||
    !Number.isInteger(expectedCardsPerStyle) ||
    expectedCardsPerStyle < 1
  ) {
    throw new Error(
      "Usage: render_page.js validate-style-gallery <index.html> <style-count> <cards-per-style>",
    );
  }
  if (!fs.existsSync(htmlPath)) {
    throw new Error(`Style gallery not found: ${htmlPath}`);
  }

  const expectedCardCount = expectedStyleCount * expectedCardsPerStyle;
  const { chromium } = loadPlaywright();
  const browser = await chromium.launch({ headless: true });
  const checks = [];
  try {
    for (const viewport of [
      { name: "desktop", width: 1440, height: 1000 },
      { name: "mobile", width: 390, height: 844 },
    ]) {
      const page = await browser.newPage({ viewport });
      const consoleErrors = [];
      page.on("console", (message) => {
        if (message.type() === "error") consoleErrors.push(message.text());
      });
      await page.goto(pathToFileURL(path.resolve(htmlPath)).href, {
        waitUntil: "load",
        timeout: 30000,
      });
      await page.waitForFunction(
        () => Array.from(document.images).every((image) => image.complete && image.naturalWidth > 0),
        null,
        { timeout: 30000 },
      );
      const result = await page.evaluate(() => ({
        pageOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
        styleCount: document.querySelectorAll(".style-section").length,
        cardCount: document.querySelectorAll(".style-card").length,
        imageCount: document.images.length,
        brokenImages: Array.from(document.images)
          .filter((image) => !image.complete || image.naturalWidth === 0)
          .map((image) => image.getAttribute("src")),
      }));
      result.name = viewport.name;
      result.consoleErrors = consoleErrors;
      if (
        result.pageOverflow !== 0 ||
        result.styleCount !== expectedStyleCount ||
        result.cardCount !== expectedCardCount ||
        result.brokenImages.length ||
        result.consoleErrors.length
      ) {
        throw new Error(`Style gallery failed at ${viewport.name}: ${JSON.stringify(result)}`);
      }
      checks.push(result);
      await page.close();
    }
  } finally {
    await browser.close();
  }
  process.stdout.write(JSON.stringify(checks));
}

async function main() {
  const args = process.argv.slice(2);
  if (args[0] === "validate-preview") {
    await validatePreview(args.slice(1));
  } else if (args[0] === "validate-style-gallery") {
    await validateStyleGallery(args.slice(1));
  } else {
    await renderCard(args);
  }
}

main().catch((error) => {
  console.error(error.stack || error.message || String(error));
  process.exit(1);
});
